import json, re, pandas as pd
te = pd.read_parquet('raw/gsm8k/main/test-00000-of-00001.parquet')
gt_by_q = dict(zip(te['question'], te['answer']))
def extract_gt(ans):
    m = re.search(r"#### (\-?[0-9\.\,]+)", ans)
    return m.group(1).replace(",", "") if m else None
gt_by_q = {q: extract_gt(a) for q,a in gt_by_q.items()}

def flexible_last_number(s):
    if len(s) > 300: s = s[-300:]
    nums = re.findall(r"(\-?[0-9\.\,]+)", s)
    for n in reversed(nums):
        if n not in ("", "."):
            return n.replace(",", "")
    return None

d = 'results/grpo_gsm8k_seed42/val_generations/60.jsonl'
mismatch=0; unmatched=0; n=0
for line in open(d):
    r = json.loads(line); n+=1
    inp = r['input']
    # extract the user question: after "user\n" up to the instruction
    m = re.search(r"user\n(.*?)Let's think step by step", inp, re.S)
    q = m.group(1).strip() if m else None
    if q is None or q not in gt_by_q:
        # question may be truncated in input display; try fuzzy: find any test question substring
        found = None
        for tq in gt_by_q:
            if tq[:60] in inp or (len(tq)>60 and tq[:40] in inp):
                found = tq; break
        q = found
    if q is None:
        unmatched+=1; continue
    my_gt = gt_by_q[q]
    my_score = 1.0 if flexible_last_number(r['output']) == my_gt else 0.0
    if my_score != r['score'] or str(r['gts']) != str(my_gt):
        mismatch+=1
        if mismatch<=5:
            print('MISMATCH: q=', q[:80]); print('  dump gts:', r['gts'], 'my_gt:', my_gt, 'dump score:', r['score'], 'my score:', my_score)
            print('  output tail:', r['output'][-200:])
print(f'checked {n} rows, unmatched={unmatched}, mismatches={mismatch}')
EOF

