import json
rows=[json.loads(l) for l in open('results/grpo_gsm8k_seed42/metrics.jsonl')]
def g(r,k):
    d=r.get('data',{})
    for kk in d:
        if kk.endswith(k): return d[kk]
    return None
hdr=['step','reward','score','val_acc','entropy','pg_loss','ppo_kl','rwd_kl','resp_len','clip','gradnorm','lr']
print(' | '.join(hdr))
for r in rows:
    d=r.get('data',{})
    step=r['step']
    if g(r,'mean@1') is None and step!=0: pass
    print(f\"{step:3d}\", end=' | ')
    for k in hdr[1:]:
        if k=='val_acc': v=g(r,'acc/mean@1')
        elif k=='reward': v=g(r,'critic/rewards/mean')
        elif k=='score': v=g(r,'critic/score/mean')
        elif k=='entropy': v=g(r,'actor/entropy')
        elif k=='pg_loss': v=g(r,'actor/pg_loss')
        elif k=='ppo_kl': v=g(r,'actor/ppo_kl')
        elif k=='rwd_kl': v=g(r,'actor/reward_kl_penalty')
        elif k=='resp_len': v=g(r,'response_length/mean')
        elif k=='clip': v=g(r,'response_length/clip_ratio')
        elif k=='gradnorm': v=g(r,'actor/grad_norm')
        elif k=='lr': v=g(r,'actor/lr')
        print(f\"{v:.4f}\" if v is not None else '  NA ', end=' | ')
    print()
"

